'use client'

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import { PhoneInput, normalizeToE164Like } from '@/components/phone-input'
import { formatPhoneForDisplay } from '@/lib/kz-phone'
import { sendWhatsAppLogin, verifyWhatsAppLoginCode } from './actions'
import { Button } from '@/components/ui/button'
import { Card } from '@/components/ui/card'

export function LoginForm({
  safeNext,
  presetPhone,
}: {
  safeNext?: string
  presetPhone?: string
}) {
  const router = useRouter()
  const [subscriber, setSubscriber] = useState(() => presetPhone ?? '')
  const [otpCode, setOtpCode] = useState('')
  const [codeRequested, setCodeRequested] = useState(false)
  const [whatsAppLoading, setWhatsAppLoading] = useState(false)
  const [otpLoading, setOtpLoading] = useState(false)
  const [message, setMessage] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)
  const isPhoneLocked = Boolean(presetPhone)

  const normalizeOtpCode = (value: string) => value.replace(/\D/g, '').slice(0, 6)

  const redirectAfterLogin = () => {
    router.push(safeNext ?? '/app/me')
    router.refresh()
  }

  const handleWhatsAppLogin = async (e: React.FormEvent) => {
    e.preventDefault()
    setWhatsAppLoading(true)
    setMessage(null)
    setError(null)

    const phoneE164 = normalizeToE164Like(subscriber)
    if (!phoneE164) {
      setError('Введите полный номер телефона (с кодом страны, например +7…).')
      setWhatsAppLoading(false)
      return
    }

    const formData = new FormData()
    formData.set('phone', phoneE164)
    const result = await sendWhatsAppLogin(formData)

    if (!result.ok) {
      setError(result.error ?? 'Не удалось отправить сообщение.')
    } else {
      setMessage(result.message ?? 'Код отправлен в WhatsApp.')
      setCodeRequested(true)
      setOtpCode('')
    }

    setWhatsAppLoading(false)
  }

  const submitWhatsAppCode = async (rawCode: string) => {
    if (!codeRequested) {
      setError('Сначала запросите код.')
      return
    }

    const code = normalizeOtpCode(rawCode)
    if (code.length !== 6) {
      setError('Введите 6-значный код.')
      return
    }

    setOtpLoading(true)
    setMessage(null)
    setError(null)

    const formData = new FormData()
    formData.set('code', code)
    const phoneE164 = normalizeToE164Like(subscriber)
    if (phoneE164) {
      formData.set('phone', phoneE164)
    }
    const result = await verifyWhatsAppLoginCode(formData)

    if (!result.ok) {
      setError(result.error ?? 'Не удалось подтвердить код.')
      setOtpLoading(false)
      return
    }

    redirectAfterLogin()
  }

  const handleVerifyWhatsAppCode = async (e: React.FormEvent) => {
    e.preventDefault()
    await submitWhatsAppCode(otpCode)
  }

  return (
    <div className="flex min-h-[60vh] items-center justify-center px-5 py-12">
      <Card className="w-full max-w-sm" padding="lg">
        <h1 className="text-3xl font-bold sm:text-4xl">Вход через WhatsApp</h1>
        <p className="mt-2 text-base leading-6 text-gray-500">
          Введите номер и подтвердите код из WhatsApp.
        </p>

        <form onSubmit={handleWhatsAppLogin} className="mt-6 space-y-4">
          <div>
            <label htmlFor="phone" className="mb-1.5 block text-base font-medium text-gray-700">
              Номер телефона
            </label>
            <PhoneInput
              id="phone"
              subscriber={subscriber}
              onSubscriberChange={setSubscriber}
              readOnly={isPhoneLocked}
              placeholder="Например: +77001234567"
              className="w-full rounded-xl border border-gray-200 px-4 py-3 text-base outline-none transition-colors placeholder:text-gray-500 focus:border-accent"
            />
            {isPhoneLocked ? (
              <p className="mt-1 text-sm text-gray-400">
                Войдите с номера {formatPhoneForDisplay(subscriber)}
              </p>
            ) : (
              <p className="mt-1 text-sm leading-6 text-gray-400">
                Для Казахстана можно +7…, 8… или 7… (11 цифр). Для других стран — с «+» и кодом.
              </p>
            )}
          </div>

          <Button
            type="submit"
            disabled={whatsAppLoading}
            className="w-full"
          >
            {whatsAppLoading ? 'Отправка...' : 'Получить код'}
          </Button>
        </form>

        {codeRequested ? (
          <form onSubmit={handleVerifyWhatsAppCode} className="mt-4 space-y-4">
            <div>
              <label htmlFor="otp" className="mb-1.5 block text-base font-medium text-gray-700">
                Код из WhatsApp
              </label>
              <input
                id="otp"
                type="text"
                required
                value={otpCode}
                inputMode="numeric"
                autoComplete="one-time-code"
                pattern="\d{6}"
                maxLength={6}
                onChange={async (e) => {
                  const next = normalizeOtpCode(e.target.value)
                  setOtpCode(next)
                  if (!otpLoading && next.length === 6) await submitWhatsAppCode(next)
                }}
                onPaste={async (e) => {
                  const pasted = e.clipboardData.getData('text')
                  const next = normalizeOtpCode(pasted)
                  if (!next) return
                  e.preventDefault()
                  setOtpCode(next)
                  if (!otpLoading && next.length === 6) await submitWhatsAppCode(next)
                }}
                placeholder="123456"
                className="w-full rounded-xl border border-gray-200 px-4 py-3 text-center text-base tracking-[0.3em] outline-none transition-colors placeholder:text-gray-500 focus:border-accent"
              />
            </div>

            <Button
              type="submit"
              variant="secondary"
              disabled={otpLoading}
              className="w-full"
            >
              {otpLoading ? 'Проверка...' : 'Подтвердить'}
            </Button>
          </form>
        ) : null}

        {message ? (
          <div className="mt-4 rounded-lg bg-emerald-50 px-3 py-2.5 text-base leading-6 text-emerald-700">
            {message}
          </div>
        ) : null}
        {error ? (
          <div className="mt-4 rounded-lg bg-red-50 px-3 py-2.5 text-base leading-6 text-red-700">
            {error}
          </div>
        ) : null}
      </Card>
    </div>
  )
}
